static Tile*tile(unsigned i){unsigned p=i/7,t=i%7;return p<config.count&&t<config.pages[p].count?&config.pages[p].tiles[t]:0;}
static int domain(const char*id,const char*d){unsigned n=len(d);for(unsigned i=0;i<n;++i)if(id[i]!=d[i])return 0;return id[n]=='.';}
